// Icons from the Central Icon System (v1.17) — outline, 1.5 stroke, radius 2, round join; "filled" for selected states.
// Generated from the Figma file, so shapes match it exactly. Paths are outlined shapes, so they use fill, not stroke.
type P = { className?: string; style?: React.CSSProperties; filled?: boolean };

function icon(outline: string, filled: string) {
  function Icon({ filled: on, ...p }: P) {
    return <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden {...p} dangerouslySetInnerHTML={{ __html: on ? filled : outline }} />;
  }
  return Icon;
}

